// Persian typesetting for the Viking contest renderer.
//
// The image model never draws letters; this module sets real Lalezar/Vazirmatn glyphs with real
// Arabic shaping. Rendering happens on @napi-rs/canvas (Skia + HarfBuzz), which shapes Persian and
// handles ZWNJ correctly, so «نیم‌فاصله» and joining forms are right without arabic-reshaper hacks.
//
// Fonts ship as WOFF2 in brand/viking/assets. Skia cannot read WOFF2, so each face is kept as a
// plain TTF in brand/viking/assets/fonts (generated by `npm run build:fonts`, committed) and
// registered by family here. If only the WOFF2 is present, we decompress to a temp file at runtime.

import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { decompress } from 'wawoff2';
import { GlobalFonts } from '@napi-rs/canvas';

const HERE = dirname(fileURLToPath(import.meta.url));
export const BRAND = resolve(HERE, '../../assets');
const TTF_DIR = join(BRAND, 'fonts');

/** face alias → [ttf filename, woff2 fallback in assets/] */
const FACES = {
  Lalezar: ['Lalezar.ttf', 'Lalezar.woff2'],
  VazirMedium: ['Vazirmatn-Medium.ttf', 'Vazirmatn-Medium.woff2'],
  VazirBold: ['Vazirmatn-Bold.ttf', 'Vazirmatn-Bold.woff2'],
  VazirBlack: ['Vazirmatn-Black.ttf', 'Vazirmatn-Black.woff2'],
};

let fontsReady = false;


/** Register every brand face once per process. Throws with a fixable message if a font is absent. */
export async function ensureFonts({ quiet = false } = {}) {
  if (fontsReady) return;
  const missing = [];
  for (const [alias, [ttfName, woff2Name]] of Object.entries(FACES)) {
    const ttfPath = join(TTF_DIR, ttfName);
    if (!existsSync(ttfPath)) {
      const woff2Path = join(BRAND, woff2Name);
      if (!existsSync(woff2Path)) {
        missing.push(woff2Name);
        continue;
      }
      mkdirSync(TTF_DIR, { recursive: true });
      const ttf = await decompress(readFileSync(woff2Path));
      writeFileSync(ttfPath, Buffer.from(ttf));
    }
    if (!GlobalFonts.registerFromPath(ttfPath, alias)) {
      throw new Error(`could not register font face ${alias} from ${ttfPath}`);
    }
  }
  if (missing.length) {
    throw new Error(
      `missing brand font(s): ${missing.join(', ')} in ${BRAND}. ` +
        'They are committed assets; restore them before rendering.',
    );
  }
  fontsReady = true;
  if (!quiet) console.log(`fonts ready: ${Object.keys(FACES).join(', ')}`);
}

// ---------------------------------------------------------------------------------------------
// Persian numerals and typography helpers
// ---------------------------------------------------------------------------------------------

const FA_DIGITS = ['۰', '۱', '۲', '۳', '۴', '۵', '۶', '۷', '۸', '۹'];

/** Convert every ASCII digit in a string to Persian digits. */
export const fa = (value) =>
  String(value).replace(/[0-9]/g, (d) => FA_DIGITS[Number(d)]);

/** Group an integer with the Persian thousands separator (٬). */
export function faNumber(value) {
  const n = Number(value);
  if (!Number.isFinite(n)) throw new Error(`faNumber expects a number, got ${value}`);
  return fa(n.toLocaleString('en-US').replace(/,/g, '٬'));
}

/** «۵۰۰» style money: value in millions → «۲٫۵» */
export const faDecimal = (value) => fa(String(value).replace('.', '٫'));

/**
 * A label/value box like the reference date capsules: small cream label above a large amber value.
 * Sizing is computed from the box so long text shrinks instead of overflowing.
 */
export function fitSize(ctx, text, { family, maxWidth, start, min = 12, weightFamily = null }) {
  const fam = weightFamily || family;
  let size = start;
  ctx.font = `${size}px ${fam}`;
  while (size > min && ctx.measureText(text).width > maxWidth) {
    size -= 1;
    ctx.font = `${size}px ${fam}`;
  }
  return size;
}

/** Text metrics including the real ink box, which is what shadows and rules must follow. */
export function inkBox(ctx, text) {
  const m = ctx.measureText(text);
  return {
    width: m.width,
    left: m.actualBoundingBoxLeft ?? 0,
    right: m.actualBoundingBoxRight ?? m.width,
    ascent: m.actualBoundingBoxAscent ?? 0,
    descent: m.actualBoundingBoxDescent ?? 0,
  };
}

/**
 * Draw one line. `align` is 'center' | 'right' | 'left'; RTL is the default for Persian copy.
 * `glow` paints a warm halo (the references have a strong amber bloom around display type) and
 * `shadow` a hard offset shadow that keeps white type readable over bright photography.
 */
export function line(ctx, text, x, y, opts = {}) {
  const {
    size = 48,
    family = 'VazirBold',
    color = '#FFFFFF',
    align = 'center',
    dir = 'rtl',
    glow = 0,
    glowColor = 'rgba(243,154,43,0.55)',
    shadow = null,
    stroke = null,
    letterSpacing = null,
    alpha = 1,
  } = opts;

  ctx.save();
  ctx.globalAlpha = alpha;
  if (letterSpacing !== null) ctx.letterSpacing = `${letterSpacing}px`;
  ctx.direction = dir;
  ctx.textAlign = align;
  ctx.textBaseline = 'alphabetic';
  ctx.font = `${size}px ${family}`;

  if (glow > 0) {
    ctx.shadowColor = glowColor;
    ctx.shadowBlur = glow;
    ctx.fillStyle = color;
    ctx.fillText(text, x, y);
    ctx.fillText(text, x, y);
    ctx.shadowBlur = 0;
  }
  if (shadow) {
    ctx.shadowColor = shadow.color || 'rgba(0,0,0,0.72)';
    ctx.shadowBlur = shadow.blur ?? 18;
    ctx.shadowOffsetY = shadow.y ?? 6;
    ctx.shadowOffsetX = shadow.x ?? 0;
  }
  if (stroke) {
    ctx.lineJoin = 'round';
    ctx.strokeStyle = stroke.color || 'rgba(0,0,0,0.85)';
    ctx.lineWidth = stroke.width ?? Math.max(2, size * 0.045);
    ctx.strokeText(text, x, y);
  }
  ctx.fillStyle = color;
  ctx.fillText(text, x, y);
  ctx.restore();
}

/** Draw a block of pre-wrapped lines with a consistent baseline rhythm. */
export function block(ctx, lines, x, y, opts = {}) {
  const { size = 48, lineHeight = 1.25, family = 'VazirBold', width = null, ...rest } = opts;
  const fam = family;
  const step = Math.round(size * lineHeight);
  const out = [];
  lines.forEach((text, i) => {
    let s = size;
    if (width) {
      ctx.font = `${s}px ${fam}`;
      s = fitSize(ctx, text, { family: fam, maxWidth: width, start: size });
    }
    line(ctx, text, x, y + i * step, { ...rest, size: s, family: fam });
    out.push(s);
  });
  return out;
}

/**
 * Split Persian copy into lines that fit `maxWidth`. Breaks on spaces only, so ZWNJ words such as
 * «می‌آید» stay intact. Explicit '\n' in the copy forces a break.
 */
export function wrap(ctx, text, { family = 'VazirBold', size = 48, maxWidth }) {
  ctx.font = `${size}px ${family}`;
  const out = [];
  for (const paragraph of String(text).split('\n')) {
    const words = paragraph.trim().split(/\s+/);
    let current = '';
    for (const word of words) {
      const candidate = current ? `${current} ${word}` : word;
      if (ctx.measureText(candidate).width <= maxWidth || !current) {
        current = candidate;
      } else {
        out.push(current);
        current = word;
      }
    }
    if (current) out.push(current);
  }
  return out;
}

/**
 * The references underline the old price with a single hand-placed red bar. Measuring the real ink
 * box keeps the bar flush with the glyphs instead of the text advance width.
 */
export function strikeBar(ctx, text, x, y, opts = {}) {
  const { size = 110, family = 'Lalezar', color = '#FF4D3D', thickness = null, angle = -0.12, pad = 10 } = opts;
  ctx.save();
  ctx.font = `${size}px ${family}`;
  ctx.direction = 'rtl';
  const m = ctx.measureText(text);
  const w = m.width + pad * 2;
  const h = thickness ?? Math.max(8, size * 0.105);
  ctx.translate(x, y - size * 0.34);
  ctx.rotate(angle);
  ctx.fillStyle = color;
  ctx.shadowColor = 'rgba(255,77,61,0.45)';
  ctx.shadowBlur = 18;
  ctx.beginPath();
  ctx.roundRect(-w / 2, -h / 2, w, h, h / 2);
  ctx.fill();
  ctx.restore();
}
